<template><div><h1>{{ project?.name }}</h1><div class="panel"><p>{{ project?.description }}</p><p>Status: {{ project?.status }} | Priority: {{ project?.priority }} | Progress: {{ project?.progress }}%</p></div><div class="panel"><h3>Tasks</h3><TaskForm @save="addTask"/><TaskList :tasks="tasks" @status="updateStatus"/></div><div class="panel"><h3>Logs / Documentation</h3><input v-model="logTitle" placeholder="Log title"/><textarea v-model="logContent" placeholder="Log content"/><button @click="addLog">Add Log</button><ul><li v-for="l in logs" :key="l.id">{{ l.title }} - {{ l.created_at }}</li></ul></div></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue';import { useRoute } from 'vue-router';import { projectService } from '../db/projectService';import { taskService } from '../db/taskService';import { logService } from '../db/logService';import TaskForm from '../components/TaskForm.vue';import TaskList from '../components/TaskList.vue';const route=useRoute();const id=Number(route.params.id);const project=ref<any>(null);const tasks=ref<any[]>([]);const logs=ref<any[]>([]);const logTitle=ref('');const logContent=ref('');const load=async()=>{project.value=await projectService.byId(id);tasks.value=await taskService.byProject(id);logs.value=await logService.byProject(id);const done=tasks.value.filter(t=>t.status==='Done').length;const progress=tasks.value.length?Math.round(done/tasks.value.length*100):0;if(project.value){project.value.progress=progress;await projectService.update(id,project.value);}};onMounted(load);const addTask=async (t:any)=>{await taskService.create({project_id:id,title:t.title,status:t.status});await load();};const updateStatus=async (taskId:any,status:string)=>{const t=tasks.value.find(x=>x.id===Number(taskId));if(!t)return;await taskService.update(t.id,{...t,status});await load();};const addLog=async()=>{if(!logTitle.value)return;await logService.create(id,logTitle.value,logContent.value);logTitle.value='';logContent.value='';await load();};</script>
